<div class="d-flex justify-content-between align-items-center mb-3"><div><h1 class="h3 mb-1">Audit Log</h1><p class="text-secondary mb-0">Immutable record of state-changing operations.</p></div></div>
<div class="card shadow-sm"><div class="card-body"><div class="row g-2 mb-3"><div class="col-md-3"><input id="from" type="date" class="form-control" value="<?=e(date('Y-m-d'))?>"></div><div class="col-md-3"><input id="to" type="date" class="form-control" value="<?=e(date('Y-m-d'))?>"></div><div class="col-md-2"><button id="load" class="btn btn-primary w-100">Refresh</button></div></div><div class="table-responsive"><table class="table table-sm align-middle" id="t"><thead><tr><th>Date</th><th>User</th><th>Action</th><th>Entity</th><th>ID</th><th>IP</th><th>Change</th></tr></thead><tbody></tbody></table></div></div></div>
<script>
$(function(){const b=<?=json_encode(url('/'),JSON_THROW_ON_ERROR)?>;function esc(v){return $('<div>').text(v??'').html();}function load(){$.getJSON(b+'audit/data',{from:$('#from').val(),to:$('#to').val()}).done(r=>{let x=$('#t tbody').empty();(r.data.rows||[]).forEach(v=>x.append('<tr><td>'+esc(v.created_at)+'</td><td>'+esc(v.username||v.full_name||'')+'</td><td>'+esc(v.action)+'</td><td>'+esc(v.entity)+'</td><td>'+esc(v.entity_id||'')+'</td><td>'+esc(v.ip||'')+'</td><td><details><summary>View</summary><pre class="small mb-0">'+esc((v.new_json||v.old_json||''))+'</pre></details></td></tr>'))})}$('#load').click(load);load();});
</script>